using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OperationsRequests.Data;using OperationsRequests.Domain;using OperationsRequests.Services;namespace OperationsRequests.Pages.Requests;[Authorize(Roles="StaffMember,SiteManager,PlatformAdmin,CountryOpsManager,TerritoryManager")]public class CreateModel(ApplicationDbContext db,UserManager<ApplicationUser> users,ScopeService scope):PageModel{[BindProperty]public InputModel Input{get;set;}=new();public List<Site> Sites{get;set;}=[];public sealed class InputModel{public string Title{get;set;}="";public string Description{get;set;}="";public int SiteId{get;set;}public RequestType Type{get;set;}public RequestPriority Priority{get;set;}}public async Task OnGetAsync()=>Sites=await db.Sites.Include(x=>x.Territory).ThenInclude(x=>x.Country).ToListAsync();public async Task<IActionResult> OnPostAsync(){await OnGetAsync();var u=await users.GetUserAsync(User);var site=Sites.SingleOrDefault(x=>x.Id==Input.SiteId);if(u is null||site is null||!scope.CanCreateAt(site,u,await users.GetRolesAsync(u))||string.IsNullOrWhiteSpace(Input.Title)||string.IsNullOrWhiteSpace(Input.Description)){ModelState.AddModelError("","Invalid request or site scope.");return Page();}var r=new TrainingRequest{RequestNumber=$"REQ-{DateTime.UtcNow:yyyy}-{Guid.NewGuid().ToString("N")[..6].ToUpperInvariant()}",Title=Input.Title,Description=Input.Description,SiteId=site.Id,RequestedById=u.Id,Type=Input.Type,Priority=Input.Priority};r.AuditEvents.Add(new AuditEvent{Action="Submitted",ActorId=u.Id,ActorName=u.DisplayName,NewStatus=r.Status,Note="Request created and submitted."});db.Add(r);await db.SaveChangesAsync();return RedirectToPage("Details",new{id=r.Id});}}
